<?php
declare(strict_types=1);

/** Migra dados Atlas para o schema-base gatlas_dbp sem alterar as fontes. */
$env=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);$env[trim($k)]=trim(trim($v),"\"'");}
$opts=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC];
function conn(array $e,string $p,string $db):PDO{return new PDO('mysql:host='.$e[$p.'_DB_HOST'].';port='.$e[$p.'_DB_PORT'].';dbname='.$db.';charset=utf8mb4',$e[$p.'_DB_USERNAME'],$e[$p.'_DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function qi(string $v):string{return '`'.str_replace('`','``',$v).'`';}
function tableCols(PDO $p,string $db,string $table):array{$s=$p->prepare('SELECT column_name FROM information_schema.columns WHERE table_schema=? AND table_name=? ORDER BY ordinal_position');$s->execute([$db,$table]);return $s->fetchAll(PDO::FETCH_COLUMN);}
function hasTable(PDO $p,string $db,string $table):bool{$s=$p->prepare("SELECT 1 FROM information_schema.tables WHERE table_schema=? AND table_name=? AND table_type='BASE TABLE'");$s->execute([$db,$table]);return (bool)$s->fetchColumn();}
function hasRoutine(PDO $p,string $db,string $name,string $type):bool{$s=$p->prepare('SELECT 1 FROM information_schema.routines WHERE routine_schema=? AND routine_name=? AND routine_type=?');$s->execute([$db,$name,$type]);return (bool)$s->fetchColumn();}
function record(PDO $p,string $code,string $origin,string $dest,string $type,int $count,array $details):void{$s=$p->prepare("INSERT INTO registros_migracao (codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES (?,?,?,?,?,'CONCLUIDA',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?) ON DUPLICATE KEY UPDATE status='CONCLUIDA',quantidade_registros=VALUES(quantidade_registros),concluida_em=CURRENT_TIMESTAMP,detalhes=VALUES(detalhes)");$s->execute([$code,$origin,$dest,$type,'0.160.0',$count,json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}
function done(PDO $p,string $code):bool{$s=$p->prepare("SELECT 1 FROM registros_migracao WHERE codigo_migracao=? AND status='CONCLUIDA'");$s->execute([$code]);return (bool)$s->fetchColumn();}
function copyData(PDO $target,PDO $source,string $sourceDb,string $targetDb,string $table,?string $targetTable=null,bool $ignore=false):int{$targetTable??=$table;$src=tableCols($source,$sourceDb,$table);$dst=tableCols($target,$targetDb,$targetTable);$by=[];foreach($dst as $c)$by[strtolower($c)]=$c;$pairs=[];foreach($src as $c){if(isset($by[strtolower($c)]))$pairs[]=[$by[strtolower($c)],$c];}if(!$pairs)throw new RuntimeException("Sem colunas comuns: $sourceDb.$table");$target->exec('DELETE FROM '.qi($targetDb).'.'.qi($targetTable));$left=implode(',',array_map(fn($x)=>qi($x[0]),$pairs));$right=implode(',',array_map(fn($x)=>qi($x[1]),$pairs));$target->exec(($ignore?'INSERT IGNORE INTO ':'INSERT INTO ').qi($targetDb).'.'.qi($targetTable).' ('.$left.') SELECT '.$right.' FROM '.qi($sourceDb).'.'.qi($table));return (int)$target->query('SELECT COUNT(*) FROM '.qi($targetDb).'.'.qi($targetTable))->fetchColumn();}
function ensureLegacyTable(PDO $target,string $targetDb,PDO $source,string $sourceDb,string $table,string $name):void{if(!hasTable($target,$targetDb,$name)){$target->exec('CREATE TABLE '.qi($targetDb).'.'.qi($name).' LIKE '.qi($sourceDb).'.'.qi($table));try{$target->exec('ALTER TABLE '.qi($targetDb).'.'.qi($name).' ENGINE=InnoDB, ROW_FORMAT=DYNAMIC, CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci');}catch(PDOException $error){$target->exec('ALTER TABLE '.qi($targetDb).'.'.qi($name).' ENGINE=InnoDB, ROW_FORMAT=DYNAMIC');}}
}

$targetDb='gatlas_dbp';$target=conn($env,'GPT',$targetDb);$source=conn($env,'LEGADO_MODELO','green_atlas');$security=conn($env,'LEGADO_SEGURANCA','green_atlas_seguranca');$adminPassword=trim((string)($env['GREEN_MIGRATION_ADMIN_PASSWORD']??getenv('GREEN_MIGRATION_ADMIN_PASSWORD')?:''));if($adminPassword==='')throw new RuntimeException('GREEN_MIGRATION_ADMIN_PASSWORD obrigatoria para criar o administrador Atlas.');$adminPasswordSql=$target->quote($adminPassword);
$target->exec('SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci');$target->exec('SET FOREIGN_KEY_CHECKS=0');
record($target,'ATLAS_SCHEMA_BASE','gmodelo_dbp','gatlas_dbp','ESTRUTURA',(int)$target->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='gatlas_dbp'")->fetchColumn(),['template'=>'gmodelo_dbp','collation'=>'utf8mb4_0900_ai_ci']);

// Configuração oficial do tenant: não copia logs, dados de teste ou empresa Modelo.
foreach(['perfis','menus','perfil_menus','setup_empresa','artefatos_replicacao'] as $table){$code='ATLAS_TEMPLATE_'.strtoupper($table);if(done($target,$code))continue;$count=copyData($target,conn($env,'GPT','gmodelo_dbp'),'gmodelo_dbp',$targetDb,$table);record($target,$code,'gmodelo_dbp.'.$table,$targetDb.'.'.$table,'ESTRUTURA',$count,['template'=>true]);}

$sourceTables=$source->query("SELECT table_name FROM information_schema.tables WHERE table_schema='green_atlas' AND table_type='BASE TABLE' ORDER BY table_name")->fetchAll(PDO::FETCH_COLUMN);
$securityTables=$security->query("SELECT table_name FROM information_schema.tables WHERE table_schema='green_atlas_seguranca' AND table_type='BASE TABLE' ORDER BY table_name")->fetchAll(PDO::FETCH_COLUMN);
$targetTables=$target->query("SELECT table_name FROM information_schema.tables WHERE table_schema='gatlas_dbp' AND table_type='BASE TABLE'")->fetchAll(PDO::FETCH_COLUMN);
$migrated=[];$legacy=[];
foreach($sourceTables as $table){if(in_array($table,['usuarios','grupos'],true))continue;$code='ATLAS_DATA_'.strtoupper($table);if(done($target,$code)||done($target,'ATLAS_LEGACY_'.strtoupper($table)))continue;if(!in_array($table,$targetTables,true)){ $name='legado_atlas_'.$table;ensureLegacyTable($target,$targetDb,$source,'green_atlas',$table,$name);$count=copyData($target,$source,'green_atlas',$targetDb,$table,$name);$legacy[]=$name;record($target,'ATLAS_LEGACY_'.strtoupper($table),'green_atlas.'.$table,$targetDb.'.'.$name,'DADOS',$count,['preservado'=>true,'motivo'=>'sem tabela equivalente no template']);continue; }
    if($table==='fo_fornecedorxusuario'){}$src=tableCols($source,'green_atlas',$table);$dst=tableCols($target,$targetDb,$table);$sl=array_map('strtolower',$src);$dl=array_map('strtolower',$dst);$extra=array_diff($sl,$dl);if($extra){$name='legado_atlas_'.$table;ensureLegacyTable($target,$targetDb,$source,'green_atlas',$table,$name);$count=copyData($target,$source,'green_atlas',$targetDb,$table,$name);$legacy[]=$name;record($target,'ATLAS_LEGACY_'.strtoupper($table),'green_atlas.'.$table,$targetDb.'.'.$name,'DADOS',$count,['preservado'=>true,'colunas_extras'=>array_values($extra)]);continue;}try{$count=copyData($target,$source,'green_atlas',$targetDb,$table);$migrated[]=$table;record($target,$code,'green_atlas.'.$table,$targetDb.'.'.$table,'DADOS',$count,['charset_origem'=>'latin1','charset_destino'=>'utf8mb4','chaves_preservadas'=>true]);}catch(PDOException $error){$name='legado_atlas_'.$table;ensureLegacyTable($target,$targetDb,$source,'green_atlas',$table,$name);$fullCount=copyData($target,$source,'green_atlas',$targetDb,$table,$name);$keptCount=copyData($target,$source,'green_atlas',$targetDb,$table,null,true);$legacy[]=$name;record($target,$code,'green_atlas.'.$table,$targetDb.'.'.$table,'DADOS',$keptCount,['status_parcial'=>'conflito_de_integridade','erro'=>$error->getMessage(),'backup_completo'=>$name,'registros_fonte'=>$fullCount,'registros_mantidos'=>$keptCount,'acao'=>'duplicidades_preservadas_no_legado']);}
}

// Segurança legada: grupos e usuários são transformados para o modelo do portal.
$target->exec('DELETE FROM `gatlas_dbp`.`grupos`');$target->exec("INSERT INTO `gatlas_dbp`.`grupos` (`codgrupo`,`nome`,`ativo`) SELECT `CODGRUPO`,CONVERT(`DSCGRUPO` USING utf8mb4),1 FROM `green_atlas_seguranca`.`grupos`");$count=(int)$target->query('SELECT COUNT(*) FROM `gatlas_dbp`.`grupos`')->fetchColumn();record($target,'ATLAS_SEGURANCA_GRUPOS','green_atlas_seguranca.grupos','gatlas_dbp.grupos','DADOS',$count,['chave_preservada'=>'CODGRUPO','conversao'=>'latin1 para utf8mb4']);
$target->exec('DELETE FROM `gatlas_dbp`.`usuarios`');$target->exec("INSERT INTO `gatlas_dbp`.`usuarios` (`codusuario`,`userid`,`nome`,`email`,`senha`,`senha_usa_hash`,`codgrupo`,`ativo`,`trocar_senha`,`criado_em`) SELECT u.`CODUSUARIO`,CONVERT(u.`USERID` USING utf8mb4),CONVERT(u.`NOME` USING utf8mb4),CONVERT(u.`EMAILS` USING utf8mb4),CONVERT(u.`SENHA` USING utf8mb4),0,(SELECT MIN(x.`CODGRUPO`) FROM `green_atlas_seguranca`.`usuariosxgrupos` x WHERE x.`CODUSUARIO`=u.`CODUSUARIO`),CASE WHEN u.`ativado`='S' THEN 1 ELSE 0 END,0,COALESCE(CAST(u.`DTINCLUSAO` AS DATETIME),CURRENT_TIMESTAMP) FROM `green_atlas_seguranca`.`usuarios` u JOIN (SELECT `USERID`,MIN(`CODUSUARIO`) `CODUSUARIO` FROM `green_atlas_seguranca`.`usuarios` WHERE `USERID` IS NOT NULL AND `USERID`<>'' GROUP BY `USERID`) first_user ON first_user.`CODUSUARIO`=u.`CODUSUARIO` WHERE u.`USERID` IS NOT NULL AND u.`USERID`<>''");$count=(int)$target->query('SELECT COUNT(*) FROM `gatlas_dbp`.`usuarios`')->fetchColumn();record($target,'ATLAS_SEGURANCA_USUARIOS','green_atlas_seguranca.usuarios','gatlas_dbp.usuarios','DADOS',$count,['chave_preservada'=>'CODUSUARIO','duplicidade_userid'=>'primeiro_CODUSUARIO','senha_usa_hash'=>0,'perfil'=>'pendente_para_usuarios_nao_admin']);

// Preserva as tabelas de segurança sem equivalente direto no modelo novo.
foreach($securityTables as $table){if(in_array($table,['usuarios','grupos','fo_fornecedorxusuario'],true))continue;if(in_array($table,$targetTables,true))continue;$code='ATLAS_LEGACY_SEGURANCA_'.strtoupper($table);if(done($target,$code))continue;$name='legado_seguranca_'.$table;ensureLegacyTable($target,$targetDb,$security,'green_atlas_seguranca',$table,$name);$count=copyData($target,$security,'green_atlas_seguranca',$targetDb,$table,$name);$legacy[]=$name;record($target,$code,'green_atlas_seguranca.'.$table,$targetDb.'.'.$name,'DADOS',$count,['preservado'=>true]);}

// Admin obrigatório do tenant, com a política de desenvolvimento documentada.
$target->exec("INSERT INTO `gatlas_dbp`.`usuarios` (`codusuario`,`userid`,`nome`,`email`,`senha`,`senha_usa_hash`,`codperfil`,`ativo`,`trocar_senha`) SELECT COALESCE((SELECT codusuario FROM usuarios WHERE userid='admin'),(SELECT COALESCE(MAX(codusuario),0)+1 FROM usuarios)),'admin','Administrador Atlas','admin@atlas.local',$adminPasswordSql,0,(SELECT codperfil FROM perfis WHERE codigo='ADMINISTRADOR'),1,0 ON DUPLICATE KEY UPDATE nome=VALUES(nome),email=VALUES(email),senha=$adminPasswordSql,senha_usa_hash=0,codperfil=VALUES(codperfil),ativo=1,trocar_senha=0");
$adminId=(int)$target->query("SELECT codusuario FROM usuarios WHERE userid='admin'")->fetchColumn();$target->exec("INSERT INTO logs_auditoria (codusuario,transacao,acao,entidade,registro_id,resultado,detalhes) SELECT $adminId,'scripts/migrar-dados-atlas.php','CRIACAO','tenant', 'ATLAS','SUCESSO',JSON_OBJECT('banco','gatlas_dbp','usuario_admin','admin') WHERE NOT EXISTS (SELECT 1 FROM logs_auditoria WHERE transacao='scripts/migrar-dados-atlas.php' AND entidade='tenant' AND registro_id='ATLAS')");
$target->exec('SET FOREIGN_KEY_CHECKS=1');
echo json_encode(['database'=>$targetDb,'migrated_tables'=>count($migrated),'legacy_tables'=>count($legacy),'users'=>(int)$target->query('SELECT COUNT(*) FROM usuarios')->fetchColumn(),'groups'=>(int)$target->query('SELECT COUNT(*) FROM grupos')->fetchColumn(),'admin'=>$adminId],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
